{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 7,
      "verse": 31,
      "source_ref": "7:31",
      "text_ar": "وقوّى نمرود نفسه، فنهض من بين إخوته، وقاتل معارك إخوته ضد جميع أعدائهم في كل مكان."
    },
    {
      "chapter": 7,
      "verse": 32,
      "source_ref": "7:32",
      "text_ar": "فَسَلَّمَ الرَّبُّ جميع أعداءِ إخوته بين يده، وَأَنْعَمَ اللهُ عليه من وقتٍ لآخر في معاركه، فَحكمَ على الأرض."
    },
    {
      "chapter": 7,
      "verse": 33,
      "source_ref": "7:33",
      "text_ar": "لِذَلِكَ صَارَ شائعًا في تلك الأيام، إِذَا قَدَّمَ رَجُلٌ الَّذينَ دَرَّبَهُم للمعركة، يَقُولُ لَهُم: كَمَا فَعَلَ اللهُ مع نمرود، الَّذي كان صَيَّادًا عظيمًا على الأرض، وَالَّذي نَجَحَ في المعارك التي سادت على إخوته، فَأَنْقَذَهُم من أيدي أعدائهم، فَلْيَقْوِي اللهُنا ويُنقذنا اليوم."
    },
    {
      "chapter": 7,
      "verse": 34,
      "source_ref": "7:34",
      "text_ar": "وعندما كان نمرود في الأربعين من عمره، كان هناك حَرْبٌ بين إخوته وأولاد يافث، فكانوا في قبضة أعدائهم."
    },
    {
      "chapter": 7,
      "verse": 35,
      "source_ref": "7:35",
      "text_ar": "فخرج نمرود في ذلك الوقت، وجمع جميع أبناء كوش وعائلاتهم، نحو أربعة مئة وستين رجلًا، واستأجر أيضًا من بعض أصدقائه ومعارفه نحو ثمانين رجلًا، ومنحهم أجورهم، فذهب معهم إلى المعركة، وعندما كان في الطريق، قوّى نمرود قلوب الناس الذين كانوا معه."
    }
  ]
}
